-- 0129 — دوازده کارت تمرین سیستمی تازه برای بانک تمرین (خواست کارفرما — باندل «طرح درمان»)
-- شکل ردیف دقیقاً الگوی 0043_exercise_seed.sql است: exercises (id ثابت لفظی، title، description، format، published، created_by
--   با گارد EXISTS staff) + برچسب‌های disorder/grade در exercise_tags (همان قرارداد tag-id مخزن) + پیوند مهارت هدف در
--   exercise_focus_links (کلیدهای برگ درخت کد: src/domain/exercise-bank/focus.ts).
-- توصیف هر کارت خودبسنده و خانواده‌محور است — کارت بدون هیچ فایل پیوستی همین امروز قابل ارسال است:
--   هدف + وسایل + مراحل شماره‌دار + قاعدهٔ والد + معیار پیشرفت. هیچ هنجار، ابزار دارای مالکیت یا متن دست‌دوم نیست.
-- قالب‌ها (EXERCISE_FORMATS در constants): worksheet | homework | game | instruction | family.
-- برچسب پایه فقط در دامنهٔ کلینیک: پیش‌دبستانی تا ششم (الگوی 0084).
-- الگوی D7: فقط-افزودنی، بدون CHECK، بدون trigger، idempotent با INSERT OR IGNORE و id ثابت لفظی.

-- ─── کارت 1 — آواشناسی خانه (نارساخوانی) ───
INSERT OR IGNORE INTO exercises (id, title, description, format, published, created_by) SELECT 'cccccccc-8200-4000-8000-000000000201','آواشناسی خانه (نارساخوانی)','هدف: تقویت آگاهی واج‌شناختی — پیش‌بینی‌کنندهٔ اصلی روانی خواندن. وسایل: هیچ؛ فقط ده واژهٔ دو یا سه‌هجایی آشنا (کِرم، سیب، تاپ، شورت، کوه، دست، ماه، گل، آسمان، توپ). روش روزانه ۵ تا ۷ دقیقه: ۱) صدای اول را بپرسید: کِرم با چه صدایی شروع می‌شود؟ ۲) صدای آخر را بپرسید. ۳) صدای وسط را با کشیدن واژه (کـــِـــرم) شکار کنید. ۴) یک صدای اول را حذف کنید: کِرم بدون صدای «کِ» چی می‌شود؟ ۵) نقش‌ها عوض شود و کودک از شما بپرسد. معیار هفتگی: هشت پاسخ درست از ده؛ با موفقیت واژه‌ها بلندتر و کمترآشنا شوند. پاسخ را جای او نگویید و «اشتباه» نگویید — فقط مدل بدهید تا خودش دوباره تلاش کند.','homework',1,(SELECT id FROM staff ORDER BY created_at LIMIT 1) WHERE EXISTS (SELECT 1 FROM staff);
INSERT OR IGNORE INTO exercise_tags (exercise_id, tag_id) SELECT 'cccccccc-8200-4000-8000-000000000201','aaaaaaaa-0000-4000-8000-000000000001' WHERE EXISTS (SELECT 1 FROM exercises WHERE id = 'cccccccc-8200-4000-8000-000000000201');
INSERT OR IGNORE INTO exercise_tags (exercise_id, tag_id) SELECT 'cccccccc-8200-4000-8000-000000000201','aaaaaaaa-0000-4000-8000-000000000102' WHERE EXISTS (SELECT 1 FROM exercises WHERE id = 'cccccccc-8200-4000-8000-000000000201');
