-- ─── کارت 2 — کارت‌های هم‌خانوادهٔ واژه (نارساخوانی) ───
INSERT OR IGNORE INTO exercises (id, title, description, format, published, created_by) SELECT 'cccccccc-8200-4000-8000-000000000202','کارت‌های هم‌خانوادهٔ واژه (نارساخوانی)','هدف: ساختن مخزن واژهٔ دیداری و پیوند صدا-حرف با خانوادهٔ واژه‌ها. وسایل: چند کارت کاغذی و مداد. روش ۷ دقیقه در روز: ۱) یک واژهٔ پایهٔ یک‌هجایی بنویسید (بار، گل، دست). ۲) با کودک خانوادهٔ واژه را بسازید: بار، باری، باران؛ گل، گلستان. ۳) هر واژهٔ جدید را دو بار بخواند: یک بار آهسته با کشیدن صداها، یک بار تند. ۴) کارت‌ها را در جعبهٔ واژه بگذارید؛ روزی سه کارت قدیمی دوباره خوانده شود. ۵) واژه‌ای که سه روز پیاپی تند و درست خوانده شد، به دیوار اتاق می‌رود. معیار: ده واژه روی دیوار تا پایان دو هفته. حجم مهم نیست؛ خواندن تند و درست مهم است.','worksheet',1,(SELECT id FROM staff ORDER BY created_at LIMIT 1) WHERE EXISTS (SELECT 1 FROM staff);
