-- ─── کارت 3 — تمرین حرف‌های آینه‌ای: ب/ت/ث/ن/ی (نارساخوانی و نارسانویسی) ───
INSERT OR IGNORE INTO exercises (id, title, description, format, published, created_by) SELECT 'cccccccc-8200-4000-8000-000000000203','تمرین حرف‌های آینه‌ای — ب/ت/ث/ن/ی (نارساخوانی و نارسانویسی)','هدف: رفع جابه‌جایی و آینه‌شدن حرف‌های هم‌شکل. وسایل: کاغذ، مداد، چند حرف مقوایی. روش ۵ تا ۷ دقیقه: ۱) سه جفت حرف هم‌شکل بنویسید (ب/ت، ب/پ، ج/چ، ن/ی). ۲) کودک با انگشت روی حرف‌ها بکشد و تفاوت نقطه‌ها را بلند بگوید: ب یک نقطهٔ پایین دارد. ۳) شما یک حرف بنویسید و او همان را کنارش کپی کند؛ سپس حرف را بپوشانید و از حافظه بنویسد. ۴) برگهٔ خطادار بسازید: در ده واژه، حرفِ آینه‌ای جا گذاشته‌اید و او درستش را پیدا و دایره بزند. معیار: هشت درست از ده در برگهٔ خطادار. تمرین کوتاه اما روزانه؛ خستگی دست علامت توقف است.','worksheet',1,(SELECT id FROM staff ORDER BY created_at LIMIT 1) WHERE EXISTS (SELECT 1 FROM staff);
