-- ─── کارت 4 — سه‌گانهٔ خط‌کشی نوشتن (نارسانویسی) ───
INSERT OR IGNORE INTO exercises (id, title, description, format, published, created_by) SELECT 'cccccccc-8200-4000-8000-000000000204','سه‌گانهٔ خط‌کشی نوشتن (نارسانویسی)','هدف: بهبود اندازه، فاصله و نشستن حرف روی خط — کیفیت، نه حجم. وسایل: برگهٔ سطرکشی (دفتر کلاس اول)، مداد خوب‌گیر. روش ۷ تا ۱۰ دقیقه در روز: ۱) خط‌کشی: زیر هر سطر با خط‌کش خط بکشید تا خط ملموس بماند. ۲) فاصله: بین دو کلمه جای انگشت کوچک بگذارید تا فاصلهٔ ثابت ساخته شود. ۳) اندازه: حرف بلند تا خط بالا، حرف کوتاه تا نیمهٔ خانه؛ دو نقطهٔ رنگی الگو راهنما باشد. ۴) فقط سه سطر بنویسد؛ سه سطر تمیز بهتر از یک صفحهٔ آشفته است. ۵) سطر امروز را با سطر دیروز مقایسه کنید و یک تفاوت مثبت بلند بگویید. معیار هفتگی: سه سطر پیاپی روی خط با فاصلهٔ پایدار.','instruction',1,(SELECT id FROM staff ORDER BY created_at LIMIT 1) WHERE EXISTS (SELECT 1 FROM staff);
