-- ─── کارت 5 — بازی مقایسهٔ مقدار با کارت‌های نقطه (نارساریاضی) ───
INSERT OR IGNORE INTO exercises (id, title, description, format, published, created_by) SELECT 'cccccccc-8200-4000-8000-000000000205','بازی مقایسهٔ مقدار با کارت‌های نقطه (نارساریاضی)','هدف: ساختن حس عدد و مقایسهٔ مقدار بدون شمارش انگشتی. وسایل: ده کارت کاغذی با یک تا ده نقطهٔ بزرگ؛ همهٔ نقطه‌ها یک‌رنگ باشند تا فقط مقدار دیده شود. روش ۷ دقیقه: ۱) دو کارت (تا ۵) نشان دهید و بپرسید کدام بیشتر؟ پاسخ تا سه ثانیه بیاید؛ اگر شمرد اشکالی ندارد، ولی کارت را دوباره نشان دهید تا ببیند نه بشمارد. ۲) بازی هم‌مقدار: کارت‌های هم‌نقطه را جفت کند. ۳) وقتی تا ۵ روان شد به ۱۰ برسید و بعد یک کارت را بپوشانید و بپرسید چند نقطه بود؟ ۴) جمع کوچک: دو کارت (جمع تا ۱۰) را ببیند و کل مقدار را با دیدن بگوید. معیار: مقایسهٔ درست در هفت جفت از ده. هر روز کوتاه؛ فشار و نمره ممنوع.','game',1,(SELECT id FROM staff ORDER BY created_at LIMIT 1) WHERE EXISTS (SELECT 1 FROM staff);
