-- ─── کارت 6 — مسئلهٔ کلامی چهارگام (نارساریاضی) ───
INSERT OR IGNORE INTO exercises (id, title, description, format, published, created_by) SELECT 'cccccccc-8200-4000-8000-000000000206','مسئلهٔ کلامی چهارگام (نارساریاضی)','هدف: چیدن راه‌حل مسئلهٔ کلامی — معمولاً سخت‌تر از خود محاسبه. وسایل: یک مسئلهٔ کلامی سادهٔ درسی و برگه. روش ۱۰ دقیقه، سه روز در هفته: گام ۱ بخوان و قصه کن: مسئله را بلند بخواند و با جملهٔ خودش قصه کند. گام ۲ بشمار: روی برگه بنویسد چه می‌دانی و چه می‌خواهد. گام ۳ عمل کن: با مهره یا رسم، عمل (جمع یا کم‌کردن) را انجام دهد و بعد نماد بنویسد. گام ۴ وارسی کن: جواب را در جملهٔ مسئله جا بزند — منطقی است؟ ۵) نقش‌ها عوض شود: او یک مسئلهٔ مشابه بسازد و شما حل کنید؛ خطای عمدی شما و اصلاح توسط او بسیار مفید است. معیار: چیدمان درست چهار گام در دو مسئلهٔ پیاپی، حتی اگر محاسبه کمکی بخواهد.','worksheet',1,(SELECT id FROM staff ORDER BY created_at LIMIT 1) WHERE EXISTS (SELECT 1 FROM staff);
