-- ─── کارت 7 — چراغ توجه: بازی سبز-قرمز خانه (بیش‌فعالی) ───
INSERT OR IGNORE INTO exercises (id, title, description, format, published, created_by) SELECT 'cccccccc-8200-4000-8000-000000000207','چراغ توجه: بازی سبز-قرمز خانه (بیش‌فعالی)','هدف: تمرین توقف و شروع (بازداری پاسخ) در قالب بازی، نه نصیحت. وسایل: یک کارت سبز و یک کارت قرمز (یا دو دستکش رنگی). روش ۷ تا ۱۰ دقیقه: ۱) قاعده را با نمایش بگویید: سبز یعنی راه بیفت یا بپر، قرمز یعنی یخ کن. ۲) ده ثانیه بازی، بعد کارت عوض شود؛ فاصله‌ها بی‌قاعده شود تا انتظار شکسته شود. ۳) مرحلهٔ دوم: سبز با دست بالا یعنی راه برو، سبز بی‌دست یعنی یخ — قاعدهٔ دوم دقت را می‌سازد. ۴) نقش عوض شود: کودک کارت را نشان دهد و شما گاهی عمدی اشتباه کنید تا او شما را گیر بیندازد. ۵) پایان بازی با شمارش: چند بار خوب یخ زدی؟ روزی یک جلسه، قبل از تکلیف نه بعدش. معیار توقف زودهنگام: دو بار درخواست توقفِ بازی.','game',1,(SELECT id FROM staff ORDER BY created_at LIMIT 1) WHERE EXISTS (SELECT 1 FROM staff);
