-- ─── کارت 8 — پنج قدم شروع کار (بیش‌فعالی) ───
INSERT OR IGNORE INTO exercises (id, title, description, format, published, created_by) SELECT 'cccccccc-8200-4000-8000-000000000208','پنج قدم شروع کار (بیش‌فعالی)','هدف: شکستن تعویق‌کاری با روتین آغازگری دیداری — کار، نه انگیزه، جا می‌افتد. روش: پنج قدم روی کاغذ A4 بزرگ بنویسید و به دیوارِ جای ثابت تکلیف بچسبانید: ۱) میز را خالی کن — فقط تکلیف امروز روی میز. ۲) تایمر را ۱۰ دقیقه بنداز و برگه را باز کن. ۳) اولین کارِ آسان را علامت بزن و انجام بده. ۴) بعد از تایمر، ۵ دقیقه بازی آزاد. ۵) تیکِ قدم را در جدول «توانستم» بزن. قواعد والد: راهنمایی فقط با اشاره به برگه، نه با تکرار لفظی؛ حذف بازی به‌عنوان جریمه ممنوع. بعد از دو هفته قدم اول را خودش انجام دهد و شما فقط چک‌لیست را ببینید. معیار: شروع کار در سه روز از پنج روز هفته بدون چانه‌زنی.','instruction',1,(SELECT id FROM staff ORDER BY created_at LIMIT 1) WHERE EXISTS (SELECT 1 FROM staff);
