-- ─── کارت 9 — ترسومتر خانه و قفسهٔ پله‌ها (اضطراب) ───
INSERT OR IGNORE INTO exercises (id, title, description, format, published, created_by) SELECT 'cccccccc-8200-4000-8000-000000000209','ترسومتر خانه و قفسهٔ پله‌ها (اضطراب)','هدف: شکستن چرخهٔ اجتناب با پله‌های کوچک مواجهه از نزدیک صفر. وسایل: کارتون، مداد رنگی، نوار چسب. روش: ۱) با کودک ترسومتر ۰ تا ۱۰ بکشید: صفر یعنی اصلاً نمی‌ترسم، ده یعنی خیلی زیاد. ۲) موقعیت‌های ترسناک را با او فهرست کنید و هر کدام نمرهٔ ۰ تا ۱۰ بگیرد؛ نمره را کودک بدهد. ۳) پله‌ها از نمرهٔ ۲ یا ۳ شروع شود، هرگز از بالای ۴. ۴) هر پله فقط وقتی بالا برود که پلهٔ قبلی دو بار انجام شده باشد. ۵) قبل و بعدِ هر پله نمرهٔ ترس را روی برگه ثبت کنید؛ پایین‌آمدن نمره را با خودِ کودک ببینید. قواعد والد: همراهِ آرام باشید و موقعیت را حذف نکنید؛ جملهٔ امن کوتاه بگویید: ترسیده‌ای، ولی می‌توانیم با هم. معیار پیشرفت: یک پلهٔ جدید در هفته.','worksheet',1,(SELECT id FROM staff ORDER BY created_at LIMIT 1) WHERE EXISTS (SELECT 1 FROM staff);
