-- ─── کارت 10 — پنج بازی واژه‌ساز خانه (اختلال زبانی) ───
INSERT OR IGNORE INTO exercises (id, title, description, format, published, created_by) SELECT 'cccccccc-8200-4000-8000-000000000210','پنج بازی واژه‌ساز خانه (اختلال زبانی)','هدف: واژه‌اندوزی و جمله‌سازی روزانه در دل بازی — پنج دقیقه، بی‌فشار. روش‌ها (هر روز یکی، به نوبت): ۱) چیه؟ یک شیء خانه را توصیف کنید (یه چیزی که سرد می‌کند، تو آشپزخانه است) تا کودک حدس بزند؛ بعد نقش عوض شود. ۲) جای خالی: جملهٔ ناتمام بگویید: توپ را به سمت … انداختم. ۳) دور خانواده: هر نفر با حرف آخر واژهٔ قبلی واژهٔ جدید می‌گوید؛ واژهٔ تکراری کنار می‌رود. ۴) عکس روز: یک عکس نشان دهید و از او بخواهید سه چیز را با جملهٔ کامل بگوید. ۵) داستان سه‌تایی: سه واژهٔ تصادفی بکشید و با هم قصهٔ کوتاه بسازید. قاعدهٔ طلایی: مدل بدهید، اصلاح لفظی نکنید؛ واژهٔ درست را در جملهٔ خودتان برگردانید. معیار هفته: استفادهٔ خودانگیخته از سه واژهٔ جدید در گفت‌وگو.','family',1,(SELECT id FROM staff ORDER BY created_at LIMIT 1) WHERE EXISTS (SELECT 1 FROM staff);
