-- ─── کارت 11 — دستور دومرحله‌ایِ بازی‌وار (بیش‌فعالی و اختلال زبانی) ───
INSERT OR IGNORE INTO exercises (id, title, description, format, published, created_by) SELECT 'cccccccc-8200-4000-8000-000000000211','دستور دومرحله‌ایِ بازی‌وار (بیش‌فعالی و اختلال زبانی)','هدف: تقویت فهم شنیداری و حافظهٔ کاری — نگه داشتن و اجرای دو گام. روش ۵ دقیقه در روز، بازی‌وار: ۱) با دستور یک‌مرحله‌ای شروع کنید و از او بخواهید بعد از اجرا دستور را بلند تکرار کند: اول چی گفتم؟ ۲) بعد دستور دومرحله‌ای بدهید: ساک را بردار و بگذار روی صندلی. ۳) ترتیب گام‌ها را عوض کنید تا حفظ‌شدگی زبانی جای فهم را نگیرد: اول تایمر را بنداز، بعد ساک را بیار. ۴) بعد از موفقیت، فاصلهٔ دو گام را با یک کار مزاحم کم‌کم زیاد کنید (گام اول، دو دقیقه بازی، گام دوم) — نسخهٔ سختِ همان بازی است. ۵) نقش عوض شود: او به شما دستور بدهد و اجرای ناقص عمدی کنید تا شما را اصلاح کند. معیار: اجرای درست دو دستور دومرحله‌ای از سه. روی خطا عصبانیت ممنوع؛ فقط دستور را تکرار کنید.','game',1,(SELECT id FROM staff ORDER BY created_at LIMIT 1) WHERE EXISTS (SELECT 1 FROM staff);
