-- ─── کارت 12 — بازی نوبت‌گیری خانه (اتیسم) ───
INSERT OR IGNORE INTO exercises (id, title, description, format, published, created_by) SELECT 'cccccccc-8200-4000-8000-000000000212','بازی نوبت‌گیری خانه (اتیسم)','هدف: تمرین هم‌چشمی، انتظار و نوبت‌گیری با قاعدهٔ دیداری — پیش‌بینی‌پذیری، پل بازی گروهی. وسایل: یک بازی سادهٔ نوبتی و یک علامت نوبت (برچسب یا دستکش). روش ۷ دقیقه: ۱) قاعده را دیداری کنید: هر که علامت نوبت را دارد بازی می‌کند؛ دیگران دست‌شان جیب است. ۲) زمان نوبت کوتاه باشد (پنج تا ده ثانیه) و پایان نوبت با تایمر بصری نشان داده شود. ۳) قبل از هر نوبت نام نوبت‌دار بلند گفته شود: نوبت مامان. ۴) یک روز در میان عضو سوم (خواهر/برادر یا شما با عروسک) وارد بازی شود تا انتظار واقعی تمرین شود. ۵) انتقال نوبت با جملهٔ ثابت اعلام شود: تمام شد — نوبت بعدی. معیار: پنج نوبت پیاپی بدون وسط‌پرانی با علامت دیداری. وسط‌پرانی را جریمه نکنید؛ فقط نوبت را برگردانید و جملهٔ ثابت را تکرار کنید.','game',1,(SELECT id FROM staff ORDER BY created_at LIMIT 1) WHERE EXISTS (SELECT 1 FROM staff);
